import { MakeLogicType, actions, connect, kea, listeners, path, reducers } from 'kea'

import { globalModalsLogic } from '~/layout/globalModalsLogic'
import { organizationLogic } from '~/scenes/organizationLogic'
import { projectLogic } from '~/scenes/projectLogic'
import { inviteLogic } from '~/scenes/settings/organization/inviteLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface modalInterruptionTrackingLogicValues {
    isCreateOrganizationModalShown: boolean // globalModalsLogic
    isCreateProjectModalShown: boolean // globalModalsLogic
    isInviteModalShown: boolean // inviteLogic
    interruptedForm: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface modalInterruptionTrackingLogicActions {
    inviteTeamMembers: () => any // inviteLogic
    createOrganization: (name: string) => string // organizationLogic
    createProject: (args_0: { name: string }) => {
        name: string
    } // projectLogic
    setInterruptedForm: (form: string | null) => {
        form: string | null
    }
}

export type modalInterruptionTrackingLogicType = MakeLogicType<
    modalInterruptionTrackingLogicValues,
    modalInterruptionTrackingLogicActions
>

export const modalInterruptionTrackingLogic = kea<modalInterruptionTrackingLogicType>([
    path(['lib', 'components', 'TimeSensitiveAuthentication', 'modalInterruptionTrackingLogic']),
    connect(() => ({
        values: [
            globalModalsLogic,
            ['isCreateOrganizationModalShown', 'isCreateProjectModalShown'],
            inviteLogic,
            ['isInviteModalShown'],
        ],
        actions: [
            organizationLogic,
            ['createOrganization'],
            projectLogic,
            ['createProject'],
            inviteLogic,
            ['inviteTeamMembers'],
        ],
    })),
    actions({
        setInterruptedForm: (form: string | null) => ({ form }),
    }),
    reducers({
        interruptedForm: [
            null as string | null,
            {
                setInterruptedForm: (_, { form }) => form,
            },
        ],
    }),
    listeners(({ actions, values }) => ({
        createOrganization: () => {
            if (values.isCreateOrganizationModalShown) {
                actions.setInterruptedForm('create_organization_modal')
            }
        },

        createProject: () => {
            if (values.isCreateProjectModalShown) {
                actions.setInterruptedForm('create_project_modal')
            }
        },

        inviteTeamMembers: () => {
            if (values.isInviteModalShown) {
                actions.setInterruptedForm('invite_members_modal')
            }
        },
    })),
])
